function csvCells(line){var result=[],value='',quoted=false;for(var i=0;i<line.length;i++){var ch=line[i];if(ch==='"'){if(quoted&&line[i+1]==='"'){value+='"';i++;}else quoted=!quoted;}else if(ch===','&&!quoted){result.push(value.trim());value='';}else value+=ch;}result.push(value.trim());return result;}
function parseQuoteCsv(text,fileName){var lines=String(text||'').replace(/^\uFEFF/,'').split(/\r?\n/).filter(function(x){return x.trim();}),errors=[],rows=[];if(lines.length<2)return {rows:rows,errors:[fileName+'：没有可导入的数据行']};var headers=csvCells(lines[0]),required=['供应商编码','含税报价(元/吨)','运费(元/吨)','账期(天)','本期最大可供量(吨)','包装袋抵扣(元/吨)','报价有效期至'],index={};required.forEach(function(name){index[name]=headers.indexOf(name);if(index[name]<0)errors.push(fileName+'：缺少字段“'+name+'”');});if(errors.length)return {rows:rows,errors:errors};for(var i=1;i<lines.length;i++){var cells=csvCells(lines[i]),code=cells[index['供应商编码']],s=S.suppliers.find(function(x){return x.sapCode===code;});if(!s){errors.push(fileName+' 第'+(i+1)+'行：供应商编码 '+code+' 不存在');continue;}if(!S.candidates.has(s.id)){errors.push(fileName+' 第'+(i+1)+'行：'+code+' 不在当前候选池');continue;}var quote=Number(cells[index['含税报价(元/吨)']]),freight=Number(cells[index['运费(元/吨)']]),paymentTerm=Number(cells[index['账期(天)']]),periodCapacity=Number(cells[index['本期最大可供量(吨)']]),bagOffset=Number(cells[index['包装袋抵扣(元/吨)']]),validTo=cells[index['报价有效期至']];if(!(quote>0)||freight<0||paymentTerm<0||!(periodCapacity>0)||bagOffset<0||!/^\d{4}-\d{2}-\d{2}$/.test(validTo)){errors.push(fileName+' 第'+(i+1)+'行：报价、运费、账期、可供量、抵扣或有效期格式不合法');continue;}rows.push({fileName:fileName,id:s.id,sapCode:s.sapCode,name:s.name,quote:quote,freight:freight,paymentTerm:paymentTerm,periodCapacity:periodCapacity,bagOffset:bagOffset,quoteValidTo:validTo});}return {rows:rows,errors:errors};}

function orderDemand(order){return Math.round(Number(order.qty||0)*Number(order.bom||0)*100)/100;}
function weightedQuantile(points,q){var rows=points.filter(function(x){return x.price>0&&x.weight>0;}).sort(function(a,b){return a.price-b.price;}),total=sum(rows,function(x){return x.weight;}),threshold=total*q,cumulative=0;if(!rows.length)return 0;for(var i=0;i<rows.length;i++){cumulative+=rows[i].weight;if(cumulative>=threshold)return rows[i].price;}return rows[rows.length-1].price;}
function orderMarketPoints(){var points=[];['internal','external'].forEach(function(source){var rows=S.orderPlan.market.filter(function(x){return x.source===source&&Number(x.price)>0&&Number(x.qty)>0;}),total=sum(rows,function(x){return Number(x.qty);});rows.forEach(function(x){points.push({price:Number(x.price),weight:Number(x.qty)/total,source:source});});});var futures=S.orderPlan.market.filter(function(x){return x.source==='futures'&&Number(x.price)>0;});futures.forEach(function(x){points.push({price:Number(x.price),weight:1/futures.length,source:'futures'});});return points;}
function orderPlanResult(){var orders=S.orderPlan.orders,totalSalesQty=sum(orders,function(x){return Number(x.qty);}),totalDemand=sum(orders,orderDemand),points=orderMarketPoints(),lower=weightedQuantile(points,.2),upper=weightedQuantile(points,.8),remaining=totalDemand,allocations=[];var candidates=S.suppliers.filter(function(s){return s.status==='准入'&&Number(s.periodCapacity)>0&&Number(s.quote)>=lower&&Number(s.quote)<=upper;}).sort(function(a,b){return unitCost(a,S.orderPlan.rate)-unitCost(b,S.orderPlan.rate);});candidates.forEach(function(s){if(remaining<=0)return;var qty=Math.min(Number(s.periodCapacity),remaining);if(qty>0){allocations.push({supplier:s,qty:qty,net:unitCost(s,S.orderPlan.rate)});remaining-=qty;}});var allocated=sum(allocations,function(x){return x.qty;}),weightedQuote=allocated?sum(allocations,function(x){return x.supplier.quote*x.qty;})/allocated:0,weightedNet=allocated?sum(allocations,function(x){return x.net*x.qty;})/allocated:0,feasible=remaining<.01&&weightedQuote>=lower&&weightedQuote<=upper;var profits=orders.map(function(order){var demand=orderDemand(order),revenue=Number(order.qty)*Number(order.salesPrice),purchaseCost=feasible?demand*weightedNet:0,manufacturingCost=feasible?Number(order.qty)*Number(order.standardManufacturingCost||0):0,otherCost=feasible?Number(order.qty)*Number(order.otherCostPerTon||0):0,totalCost=purchaseCost+manufacturingCost+otherCost,profit=feasible?revenue-totalCost:0;return {order:order,demand:demand,revenue:revenue,purchaseCost:purchaseCost,manufacturingCost:manufacturingCost,otherCost:otherCost,totalCost:totalCost,profit:profit,margin:revenue?profit/revenue*100:0};}),totalPurchaseCost=sum(profits,function(x){return x.purchaseCost;}),totalManufacturingCost=sum(profits,function(x){return x.manufacturingCost;}),totalOtherCost=sum(profits,function(x){return x.otherCost;}),totalCost=sum(profits,function(x){return x.totalCost;});return {totalSalesQty:totalSalesQty,totalDemand:totalDemand,lower:lower,upper:upper,allocations:allocations,allocated:allocated,remaining:Math.max(0,remaining),weightedQuote:weightedQuote,weightedNet:weightedNet,feasible:feasible,profits:profits,totalPurchaseCost:totalPurchaseCost,totalManufacturingCost:totalManufacturingCost,totalOtherCost:totalOtherCost,totalCost:totalCost,purchaseShare:totalCost?totalPurchaseCost/totalCost*100:0,manufacturingShare:totalCost?totalManufacturingCost/totalCost*100:0,otherShare:totalCost?totalOtherCost/totalCost*100:0,totalProfit:sum(profits,function(x){return x.profit;})};}
