  var recordsSection='<div class="card mb-16"><div class="proc2-chart-title"><div><div class="card-title"><span class="dot" style="background:var(--purple)"></span>已发布预测提报</div><small>当前方案引用的已发布预测记录</small></div><span class="proc2-axis-note">'+shortDate(first.startDate)+' 至 '+shortDate(last.endDate)+'</span></div><div class="proc2-price-compare"><span>当前方案引用 <b>'+list.length+' 份</b></span><span>数值预测 <b>'+numeric.length+' 份</b></span><span>定性预测 <b>'+trends.length+' 份</b></span><span>原料 <b>'+esc(currentPlan().material)+'</b></span></div><div class="proc2-forecast-sources proc2-forecast-source-grid">'+list.map(function(f){return '<button class="proc2-forecast-source" onclick="proc2ViewForecastModal(\''+f.id+'\')"><span>'+tag(forecastMethodLabel(f.method),forecastMethodTone(f.method))+' '+tag(f.status)+'</span><b>'+f.id+'</b><small>'+shortDate(f.startDate)+'—'+shortDate(f.endDate)+' · '+f.owner+' · '+f.publishedAt.slice(5,16)+'</small><em>'+esc(forecastSummary(f))+'</em></button>';}).join('')+'</div></div>';
