function initRollingChart(){if(typeof initChart!=='function'||!S.rollingSolution||!document.getElementById('proc2RollingChart'))return;var r=D.rolling;initChart('proc2RollingChart',mOpt({tooltip:{trigger:'axis',axisPointer:{type:'shadow'},valueFormatter:function(v){return fmt(v)+'吨';}},grid:{left:58,right:18,top:20,bottom:46},xAxis:{type:'category',axisLabel:{interval:0},data:['需求大幅增加','无限期延期','质量问题终止']},yAxis:{type:'value',name:'吨'},series:[{name:'纳入调整量',type:'bar',barMaxWidth:54,label:{show:true,position:'top',formatter:function(p){return fmt(p.value)+'吨';}},itemStyle:{color:'rgba(245,158,11,.78)'},data:[r.demandIncreaseQty,r.riskItems[0].replanQty,r.riskItems[1].replanQty]}]}));}
