window.initProcurement=function(){render();};
window.navigateProcurement=function(section){S.section=section||'orderplan';S.navExpanded=true;S.forecastEditing=false;S.forecastDraft=null;if(S.section!=='plans')S.workspace=false;navigate('procurement');};
